<?php
require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php';
$page_title='Assignments';$msg='';$err='';$teacher=$_SESSION['username'];require_once '../includes/teacher_context.php';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['create_assignment'])){
    $assignmentId=(int)($_POST['teaching_assignment_id']??0);$ctx=teacher_context_valid_assignment($conn,$teacher,$assignmentId,$teacher_context_semester);$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$due=$_POST['due_date']??'';
    if(!$ctx)$err='Select a valid subject from your current teaching context.';elseif($title===''||$due==='')$err='Enter an assignment title and due date.';elseif($due<date('Y-m-d'))$err='Due date cannot be before today.';else{$st=$conn->prepare("INSERT INTO tbl_assignments(teacher_username,batch_id,semester,title,subject,description,due_date) VALUES(?,?,?,?,?,?,?)");$st->bind_param('siissss',$teacher,$ctx['batch_id'],$ctx['semester'],$title,$ctx['subject'],$description,$due);if($st->execute())$msg='Assignment assigned to '.$ctx['batch_name'].' · Semester '.$ctx['semester'].' · '.$ctx['subject'].'.';else$err='Unable to create the assignment.';}
}
if(isset($_GET['review'])){$id=(int)$_GET['review'];$st=$conn->prepare("UPDATE tbl_student_assignments SET assignment_status=1 WHERE id=? AND teacher_username=?");$st->bind_param('is',$id,$teacher);$st->execute();header('Location: assignments.php');exit;}
$st=$conn->prepare("SELECT a.*,b.batch_name,b.course FROM tbl_assignments a LEFT JOIN tbl_batches b ON b.id=a.batch_id WHERE a.teacher_username=? ORDER BY a.id DESC");$st->bind_param('s',$teacher);$st->execute();$assignments=$st->get_result();$st=$conn->prepare("SELECT sa.*,a.title,a.due_date,a.batch_id,a.semester,b.batch_name FROM tbl_student_assignments sa INNER JOIN tbl_assignments a ON a.id=sa.assignment_id LEFT JOIN tbl_batches b ON b.id=a.batch_id WHERE sa.teacher_username=? ORDER BY sa.id DESC");$st->bind_param('s',$teacher);$st->execute();$submissions=$st->get_result();
require '../includes/header.php';
?>
