<div class="col-xl-7"><div class="glass-card mb-4"><div class="section-kicker">MY ASSIGNMENTS</div><div class="table-responsive"><table class="table"><thead><tr><th>Assignment</th><th>Class</th><th>Due</th></tr></thead><tbody><?php if($assignments->num_rows===0):?><tr><td colspan="3" class="empty">No assignments yet.</td></tr><?php endif;?><?php while($a=$assignments->fetch_assoc()):?><tr><td><strong><?php echo e($a['title']);?></strong><br><span class="small-muted"><?php echo e($a['subject']);?></span></td><td><?php echo e(($a['batch_name']??'Unassigned').' · Sem '.($a['semester']??'-'));?></td><td><?php echo e($a['due_date']);?></td></tr><?php endwhile;?></tbody></table></div></div><div class="glass-card"><div class="section-kicker">SUBMISSIONS</div><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Assignment</th><th>Class</th><th>File</th><th>Status</th></tr></thead><tbody><?php if($submissions->num_rows===0):?><tr><td colspan="5" class="empty">No submissions yet.</td></tr><?php endif;?><?php while($r=$submissions->fetch_assoc()):?><tr><td><?php echo e($r['username']);?></td><td><?php echo e($r['title']);?></td><td><?php echo e($r['batch_name']??'-');?> · Sem <?php echo e($r['semester']??'-');?></td><td><a target="_blank" href="../uploads/assignments/<?php echo rawurlencode(basename($r['assignment_file_path']));?>">Open</a></td><td><?php if($r['assignment_status']):?><span class="badge text-bg-success">Reviewed</span><?php else:?><a class="btn btn-sm btn-primary" href="?review=<?php echo (int)$r['id'];?>">Review</a><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></div>
